186			t.Fatalf("set overwriting offender: got res=%+v f=%+v, want invalid_request", res, f)
187		}
188	
189		// The same holds when the direct byte is in the name the set rule would
190		// merge away.
191		res, f = Resolve(setCfg, &Request{Method: "GET", Target: "/p?x\t=1&a=2"})
192		if f == nil || f.Code != "invalid_request" || res != nil {
193			t.Fatalf("set with offending name: got res=%+v f=%+v, want invalid_request", res, f)
194		}
195	}
196	
197	// TestTargetPercentEncodedControlCharactersUnaffected pins the distinction
198	// between direct and percent-encoded bytes: an encoded space, tab, newline,
199	// null or DEL is data, matching and joining keep the raw escape byte for
200	// byte (path escapes are never decoded before prefix matching), the query
201	// rules keep comparing decoded names and rewriting as before, and nothing is
202	// re-encoded, deleted or reordered. Non-ASCII content keeps its existing
203	// behavior too.
204	func TestTargetPercentEncodedControlCharactersUnaffected(t *testing.T) {
205		cfg := mustConfig(t, sampleConfig)
206		cases := []struct {
207			name     string
208			target   string
209			routeID  string
210			upstream string
211		}{
212			{
213				name:     "encoded space extends the segment, so /api/orders prefix does not match",
214				target:   "/api/orders%20next",
215				routeID:  "api",
216				upstream: "http://api.internal/v1/orders%20next",
217			},
218			{
219				name:     "encoded newline and tab in a query value stay verbatim",
220				target:   "/api/orders?note=%0A%09",
221				routeID:  "orders",
222				upstream: "http://orders.internal/?note=%0A%09",
223			},
224			{
225				name:     "encoded space in a path segment matches the raw prefix",
226				target:   "/users/a%20b",
227				routeID:  "users",
228				upstream: "http://users.internal/u/a%20b",
229			},
230			{
231				name:     "encoded null and del in a query value stay verbatim",
232				target:   "/api?x=%00%7F",
233				routeID:  "api",
234				upstream: "http://api.internal/v1/?x=%00%7F",
235			},
236			{
237				name:     "encoded control byte in a parameter name is still a parameter",
238				target:   "/api?a%09b=1",
239				routeID:  "api",
240				upstream: "http://api.internal/v1/?a%09b=1",
241			},
242			{
243				name:     "non ascii path and query keep their existing behavior",
244				target:   "/api/orders?note=中文&p=/订单",
245				routeID:  "orders",
246				upstream: "http://orders.internal/?note=中文&p=/订单",
247			},
248		}
249		for _, tc := range cases {
250			t.Run(tc.name, func(t *testing.T) {
251				req, f := ParseRequest(requestJSONString(t, "GET", tc.target))
252				if f != nil {
253					t.Fatalf("ParseRequest(%q): unexpected failure %+v", tc.target, f)
254				}
255				res, rf := Resolve(cfg, req)
256				if rf != nil {
257					t.Fatalf("Resolve(%q): unexpected failure %+v", tc.target, rf)
258				}
259				if res.RouteID != tc.routeID {
260					t.Errorf("routeId = %q, want %q", res.RouteID, tc.routeID)
261				}
262				if res.UpstreamURL != tc.upstream {
263					t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.upstream)
264				}
265			})
266		}
267	
268		// Transforms still compare decoded names and rewrite only the hit
269		// parameter; a parameter carrying encoded control bytes is never touched.
270		got := transformResult(t, `[{"op":"remove","name":"a"}]`, "/p?note=%0A%09&a=1")
271		if want := "http://h.internal/base/p?note=%0A%09"; got != want {
272			t.Fatalf("upstreamURL = %q, want %q", got, want)
273		}
274		got = transformResult(t, `[{"op":"set","name":"a","value":""}]`, "/p?x=%00%7F&a=1")
275		if want := "http://h.internal/base/p?x=%00%7F&a="; got != want {
276			t.Fatalf("upstreamURL = %q, want %q", got, want)
277		}
278	}
279	
280	// TestTargetCharacterRulePrecedence pins the order of the request checks:
281	// config errors keep winning before the request is examined at all (CLI),
282	// and within one request syntax, shape, field types, method content and the
283	// existing target checks (absolute target, fragment, malformed percent
284	// escape) all precede the new direct-character rule.
285	func TestTargetCharacterRulePrecedence(t *testing.T) {
286		// A malformed percent escape is reported before the direct newline later
287		// in the same target.
288		for _, src := range []string{
289			`{"method":"GET","target":"/a%zz\n"}`,
290			`{"method":"GET","target":"/a%2\n"}`,
291		} {
292			_, f := ParseRequest([]byte(src))
293			if f == nil || f.Code != "invalid_request" {
294				t.Fatalf("%s: got %+v, want invalid_request", src, f)
295			}
296			if !strings.Contains(f.Reason, "percent escape") {
297				t.Fatalf("%s: reason = %q, want the percent-escape reason first", src, f.Reason)
298			}
299			if strings.Contains(f.Reason, "U+") {
300				t.Fatalf("%s: percent-escape check must precede the character check: %q", src, f.Reason)
301			}
302		}
303	
304		// Fragment check precedes the direct character after the '#'.
305		_, f := ParseRequest([]byte(`{"method":"GET","target":"/a#f\n"}`))
306		if f == nil || !strings.Contains(f.Reason, "fragment") {
307			t.Fatalf("got %+v, want the fragment reason first", f)
308		}
309	
310		// A non-absolute target precedes the character rule.
311		_, f = ParseRequest([]byte(`{"method":"GET","target":"a b\n"}`))
312		if f == nil || !strings.Contains(f.Reason, "start with /") {
313			t.Fatalf("got %+v, want the start-with-/ reason first", f)
314		}
315	
316		// Method content precedes the target character rule.
317		_, f = ParseRequest([]byte(`{"method":"GE T","target":"/a\n"}`))
318		if f == nil || !strings.Contains(f.Reason, "legal HTTP method") {
319			t.Fatalf("got %+v, want the method reason first", f)
320		}
321	
322		// A bad config still beats a target with a direct newline: ParseConfig
323		// fails and hands back no config at all.
324		badCfg := `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"ftp://h"}]}`
325		cfg, cf := ParseConfig([]byte(badCfg))
326		if cf == nil || cf.Code != "invalid_config" {
327			t.Fatalf("got cfg=%+v f=%+v, want invalid_config", cfg, cf)
328		}
329		if cfg != nil {
330			t.Fatal("a rejected config must not be returned")
331		}
332	}
