1	package contractsentinel
2	
3	import (
4		"strings"
5		"testing"
6	)
7	
8	// These tests pin the raw-encoded prefix matching contract: a configured
9	// pathPrefix is matched against the request path byte for byte, exactly as
10	// written. Prefixes that would decode to the same path but are spelled
11	// differently — "/files/a%2Fb" vs "/files/a%2fb" vs "/files/a/b", or
12	// "/item/A" vs "/item/%41" — are different routes, and a request selects
13	// only the route whose raw spelling its own raw path hits. Matching never
14	// decodes the path and never normalizes the case of percent escapes, the
15	// query string never contributes candidates, and a "%2F" (either case)
16	// directly after a prefix is the same segment continuing, not a separator.
17	
18	// rawPrefixConfig holds three routes whose prefixes all decode to
19	// "/files/a/b" but are spelled three different ways, plus a root fallback.
20	const rawPrefixConfig = `{
21	  "routes": [
22	    {"id": "enc-upper", "methods": ["GET"], "pathPrefix": "/files/a%2Fb", "upstream": "http://upper.internal/u"},
23	    {"id": "enc-lower", "methods": ["GET"], "pathPrefix": "/files/a%2fb", "upstream": "http://lower.internal/l"},
24	    {"id": "plain",     "methods": ["GET"], "pathPrefix": "/files/a/b",   "upstream": "http://plain.internal/p"},
25	    {"id": "root",      "methods": ["*"],   "pathPrefix": "/",            "upstream": "http://fallback.internal/base"}
26	  ]
27	}`
28	
29	func TestResolveRawEncodedPrefixSelectedVerbatim(t *testing.T) {
30		// One legal config carries all three spellings at once. Each request is
31		// served only by the route its raw path spelling hits; decoding the path
32		// or unifying the escape case would merge the three routes into one and
33		// must never change the selection.
34		cases := []struct {
35			name     string
36			target   string
37			routeID  string
38			upstream string
39		}{
40			{
