260			t.Errorf("upstreamURL = %q, want %q", success.UpstreamURL, want)
261		}
262	}
263	
264	// TestResolveCLIEndedInputRequestErrors pins the other side of the timing
265	// contract: once stdin has ended, whatever arrived is the whole request. A
266	// closed pipe carrying broken JSON is invalid_request, and a closed pipe that
267	// delivered nothing at all is invalid_request too — both unlike a
268	// temporarily empty pipe that is still open. Each failure exits non-zero,
269	// leaves stdout completely empty and emits one JSON error on stderr.
270	func TestResolveCLIEndedInputRequestErrors(t *testing.T) {
