		{"json capitalized unicode escape for space", `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"/a\u0020b","upstream":"http://h"}]}`, "U+0020"},
		{"json newline escape", `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"/a\n","upstream":"http://h"}]}`, "U+000A"},
