244	// TestConfigPrefixPercentEncodedControlCharactersUnaffected pins the other
245	// half of the rule at the config and resolve boundary: percent-encoded bytes
246	// are not direct characters. A prefix such as /a%20b stays a legal
247	// configuration and matches /a%20b/items on the raw encoded spelling; "%09",
248	// "%00" and "%7F" keep working as raw text too, the escape case and segment
249	// boundaries are preserved, and the encoded bytes reach upstreamURL byte for
250	// byte with no decoding or re-encoding.
251	func TestConfigPrefixPercentEncodedControlCharactersUnaffected(t *testing.T) {
252		cfg := mustConfig(t, `{"routes":[
253		  {"id":"spaced","methods":["GET"],"pathPrefix":"/a%20b","upstream":"http://spaced.internal/s"},
254		  {"id":"ctrl","methods":["GET"],"pathPrefix":"/t%09x%00","upstream":"http://ctrl.internal/c"},
255		  {"id":"lower","methods":["GET"],"pathPrefix":"/a%2fb","upstream":"http://lower.internal/l"},
256		  {"id":"cn","methods":["*"],"pathPrefix":"/中文","upstream":"http://cn.internal/中"}
257		]}`)
258		cases := []struct {
259			name     string
260			target   string
261			routeID  string
262			upstream string
263		}{
264			{
265				name:     "encoded space prefix matches the encoded request",
266				target:   "/a%20b/items",
267				routeID:  "spaced",
268				upstream: "http://spaced.internal/s/items",
269			},
270			{
271				name:     "exact encoded prefix keeps one junction slash",
272				target:   "/a%20b",
273				routeID:  "spaced",
274				upstream: "http://spaced.internal/s/",
275			},
276			{
277				name:     "encoded space extends the segment, so a bare /a does not boundary-match",
278				target:   "/a%20b%2Fcontinue",
279				routeID:  "spaced",
280				upstream: "http://spaced.internal/s/%2Fcontinue",
281			},
282			{
283				name:     "encoded tab and null in a prefix match raw",
284				target:   "/t%09x%00/y",
285				routeID:  "ctrl",
286				upstream: "http://ctrl.internal/c/y",
287			},
288			{
289				name:     "uppercase %2F in the prefix keeps its case and is a segment, not a slash",
290				target:   "/a%2fb/x",
291				routeID:  "lower",
292				upstream: "http://lower.internal/l/x",
293			},
294			{
295				name:     "chinese prefix and chinese remainder are unaffected",
296				target:   "/中文/订单",
297				routeID:  "cn",
298				upstream: "http://cn.internal/中/订单",
299			},
300		}
301		for _, tc := range cases {
302			t.Run(tc.name, func(t *testing.T) {
303				res := resolveJSON(t, cfg, `{"method":"GET","target":"`+tc.target+`"}`)
304				if res.RouteID != tc.routeID {
305					t.Errorf("routeId = %q, want %q", res.RouteID, tc.routeID)
306				}
307				if res.UpstreamURL != tc.upstream {
308					t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.upstream)
309				}
310			})
311		}
312	
313		// A literal-space request must not hit an encoded-space prefix: the
314		// request is invalid_request on its own merits, and the encoded route
315		// never serves a decoded spelling.
316		_, rf := ParseRequest(prefixConfigJSON(t, "GET", "/a%20b/items", "http://h"))
317		if rf == nil || rf.Code != "invalid_request" {
318			t.Fatalf("request marshaled with a literal-space target: got %+v, want invalid_request", rf)
319		}
320		res, f := Resolve(cfg, &Request{Method: "GET", Target: "/a b/items"})
321		if f == nil || f.Code != "invalid_request" || res != nil {
322			t.Fatalf("literal-space target: got res=%+v f=%+v, want invalid_request only", res, f)
323		}
324	
325		// A request whose path spells the prefix with a decoded space does not
326		// match the encoded route: with a root fallback it falls through to it.
327		withFallback := mustConfig(t, `{"routes":[
328		  {"id":"spaced","methods":["GET"],"pathPrefix":"/a%20b","upstream":"http://spaced.internal/s"},
329		  {"id":"root","methods":["*"],"pathPrefix":"/","upstream":"http://fallback.internal/base"}
330		]}`)
331		// The only legal way to send a space in the target is encoded; a request
332		// to a different encoded spelling must not match /a%20b either.
